namespace ChilliCream.Nitro.CommandLine.Services.Hook;

/// <summary>
/// Builds the Opencode plugin shim installed by the hooks command.
/// </summary>
internal static class OpencodeHooksTemplate
{
    public const string OwnershipMarker = "nitro-opencode-hooks: managed";

    public static string Build(LaunchDescriptor descriptor)
    {
        var command = new List<string>(1 + descriptor.ArgumentPrefix.Count) { descriptor.Executable };
        command.AddRange(descriptor.ArgumentPrefix);

        return $$"""
            // {{OwnershipMarker}}
            // Generated by Nitro. Changes are replaced by `nitro agent hooks opencode install`.
            const command = {{BuildCommandArray(command)}};
            const timeoutMilliseconds = 10_000;
            const nitroPushedPrefix = "{{EscapeJavaScriptString(OpencodeHookProtocol.PushedPromptPrefix)}}";
            const activeSessions = new Map();

            function sessionId(properties) {
              return properties.sessionID ?? properties.sessionId ?? properties.session?.id ?? properties.info?.id;
            }

            function payload(properties, serverUrl) {
              const result = {
                serverUrl: serverUrl.toString(),
                sessionId: sessionId(properties),
              };

              if (process.env.OPENCODE_SERVER_PASSWORD) {
                result.serverPassword = process.env.OPENCODE_SERVER_PASSWORD;
              }

              return result;
            }

            async function invoke(name, body) {
              try {
                const child = Bun.spawn([...command, "agent", "hook", "opencode", name], {
                  stdin: "pipe",
                  stdout: "pipe",
                  stderr: "ignore",
                });
                child.stdin.write(JSON.stringify(body));
                child.stdin.end();

                const text = await Promise.race([
                  new Response(child.stdout).text(),
                  new Promise((_, reject) => setTimeout(() => reject(new Error("timeout")), timeoutMilliseconds)),
                ]);
                const exitCode = await child.exited;

                return exitCode === 0 && text ? JSON.parse(text) : {};
              } catch {
                return {};
              }
            }

            function nextSyntheticPartId(existingParts) {
              let maxId = null;

              for (const part of existingParts ?? []) {
                if (typeof part?.id === "string" && part.id.startsWith("prt_")) {
                  if (maxId === null || part.id > maxId) {
                    maxId = part.id;
                  }
                }
              }

              return maxId ?? `prt_${Date.now().toString(36)}${Math.random().toString(36).slice(2)}`;
            }

            function syntheticTextOf(part) {
              if (typeof part === "string") {
                return part;
              }

              if (part?.type === "text" && typeof part.text === "string") {
                return part.text;
              }

              return undefined;
            }

            // opencode's chat.message hook passes FULL Parts on output.parts, not
            // TextPartInputs: a stored Part requires id, sessionID and messageID, and a
            // part missing any of them kills the user's prompt with a 500 (see
            // SessionHttpApi.prompt). sessionID/messageID must come from
            // output.message, never from output.parts[0], which can be empty.
            // Ordering everywhere is a plain string sort on id, so growing the
            // lexicographic max sibling id by one "z" per appended part always sorts
            // last. The whole function is wrapped in try/catch: missing context is an
            // acceptable degradation, a rejected prompt is not.
            function appendParts(output, response) {
              try {
                const sessionID = output.message?.sessionID;
                const messageID = output.message?.id;

                if (!sessionID || !messageID) {
                  return;
                }

                const parts = response.parts ?? response.additionalContext ?? [];
                let previousId = nextSyntheticPartId(output.parts);

                for (const part of parts) {
                  const text = syntheticTextOf(part);

                  if (text === undefined) {
                    continue;
                  }

                  previousId = `${previousId}z`;
                  output.parts.push({
                    id: previousId,
                    sessionID,
                    messageID,
                    type: "text",
                    text,
                    synthetic: true,
                  });
                }
              } catch {
                // Missing or malformed context is an acceptable degradation; a
                // rejected prompt is not.
              }
            }

            function stripNitroPushedPrefix(parts) {
              let pushed = false;

              for (const part of parts ?? []) {
                if (part?.type === "text" && typeof part.text === "string" && part.text.startsWith(nitroPushedPrefix)) {
                  part.text = part.text.slice(nitroPushedPrefix.length);
                  pushed = true;
                }
              }

              return pushed;
            }

            export default async function nitroHooks(input) {
              const serverUrl = input.serverUrl;

              process.on("exit", () => {
                for (const [id, version] of activeSessions) {
                  void invoke("session-deleted", {
                    ...payload({ sessionID: id }, serverUrl),
                    harnessVersion: version,
                  });
                }
              });

              return {
                event: async ({ event }) => {
                  const properties = event.properties ?? {};
                  const body = payload(properties, serverUrl);

                  if (event.type === "session.created") {
                    body.harnessVersion = properties.info?.version ?? properties.session?.version;
                    if (body.sessionId) {
                      activeSessions.set(body.sessionId, body.harnessVersion);
                    }
                    await invoke("session-created", body);
                  } else if (event.type === "session.deleted") {
                    activeSessions.delete(body.sessionId);
                    await invoke("session-deleted", body);
                  } else if (
                    event.type === "session.idle" ||
                    (event.type === "session.status" && properties.status?.type === "idle")) {
                    await invoke("session-idle", body);
                  }
                },
                "chat.message": async (input, output) => {
                  // OpenCode exposes the message actually delivered to the
                  // model on output.parts, not input.parts, so the pushed
                  // prefix must be read and stripped there.
                  const nitroPushed = stripNitroPushedPrefix(output.parts);
                  const response = await invoke("chat-message", {
                    ...payload({ sessionID: input.sessionID ?? input.sessionId }, serverUrl),
                    nitroPushed,
                  });
                  appendParts(output, response);
                },
                dispose: async () => {
                  // Session deletion is the authoritative cleanup path. This is best effort only.
                },
              };
            }
            """;
    }

    private static string BuildCommandArray(IReadOnlyList<string> command)
        => $"[{string.Join(',', command.Select(static part => $"\"{EscapeJavaScriptString(part)}\""))}]";

    private static string EscapeJavaScriptString(string value)
        => value.Replace("\\", "\\\\", StringComparison.Ordinal)
            .Replace("\"", "\\\"", StringComparison.Ordinal)
            .Replace("\r", "\\r", StringComparison.Ordinal)
            .Replace("\n", "\\n", StringComparison.Ordinal);
}
